{
    v := "";
    for i := 0 to |s|


    {
        if IsLowerCase(s[i]) {
            var C : char := ShiftMinus32(s[i]);


            v := v + [C];
        } else if IsUpperCase(s[i]) {
            var c : char := Shift32(s[i]);


            v := v + [c];
        } else {
            v := v + [s[i]];
        }
    }
}

