{
  var s := 0.0;
  i := -1;
  var k := 0;
  while k < A.Length







  {


    var nextSum := s + A[k];
    if nextSum > (p/100.0) * total {
      break;
    } else {
      s := nextSum;
      i := k;
      k := k + 1;
    }
  }
  if k == A.Length {
    i := A.Length - 1;
  }
}

